import { useEffect, useState } from "react";
import { toast, Toaster } from "sonner";
import { Activity, ArrowLeft, ArrowRight, BookOpen, Check, ChevronDown, CircleHelp, Database, Eye, FileJson, FlaskConical, KeyRound, Layers3, Plus, RotateCcw, Search, Settings2, ShieldCheck, Sun, Moon, Trash2, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetDescription, SheetFooter, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupContent, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { Switch } from "@/components/ui/switch";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { copy, delta, exposed, fixture, keyImpact, members, origin, same, toggleModel, type Access, type Campaign, type Capability, type Demo, type Group, type Key, type Model, type Policy } from "./demo";

type Page = "models" | "groups" | "keys" | "qualification";
type Confirm = { title: string; text: string; action: () => void } | null;
const nav: { id: Page; label: string; icon: typeof Database }[] = [
  { id: "models", label: "Model Catalog", icon: Database },
  { id: "groups", label: "Groups", icon: Layers3 },
  { id: "keys", label: "Virtual Keys", icon: KeyRound },
  { id: "qualification", label: "Qualification", icon: FlaskConical },
];
const formats: Policy["naming"][] = ["model", "provider/model", "both"];
const statusStyle = (s: string) => s === "Observed in simulated campaign" || s === "Pass" || s === "Configured" ? "success" : s === "Unknown" || s === "Inconclusive" ? "warning" : "secondary";
function UiSelect({ label, value, options, onChange, className = "" }: { label: string; value: string; options: string[]; onChange: (value: string) => void; className?: string }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className={className}><SelectValue /></SelectTrigger><SelectContent>{options.map(option => <SelectItem key={option} value={option}>{option}</SelectItem>)}</SelectContent></Select>;
}
const scenariosFor = (model?: Model) => model?.kind === "Image" ? ["Image generation"] : model?.kind === "Embedding" ? ["Embeddings"] : ["Chat completion", "Streaming", "Tool round trip", "Vision input"];

function route(): { page: Page; id?: string } {
  const [page, id] = location.hash.slice(2).split("/");
  return { page: nav.some(n => n.id === page) ? page as Page : "models", id };
}

export function App() {
  const [data, setData] = useState<Demo>(() => copy(fixture));
  const [locationState, setLocationState] = useState(route);
  const [search, setSearch] = useState("");
  const [family, setFamily] = useState("All providers");
  const [kind, setKind] = useState("All types");
  const [modelDraft, setModelDraft] = useState<Model | null>(null);
  const [creatingModel, setCreatingModel] = useState(false);
  const [modelError, setModelError] = useState("");
  const [groupDraft, setGroupDraft] = useState<Group | null>(null);
  const [keyForm, setKeyForm] = useState<{ name: string; client: string } | null>(null);
  const [renameForm, setRenameForm] = useState<{ id: string; name: string } | null>(null);
  const [campaignForm, setCampaignForm] = useState<{ access: string; scenario: string; outcome: Campaign["outcome"] } | null>(null);
  const [report, setReport] = useState<Campaign | null>(null);
  const [dark, setDark] = useState(() => document.documentElement.classList.contains("dark"));
  useEffect(() => { document.documentElement.classList.toggle("dark", dark); document.documentElement.style.colorScheme = dark ? "dark" : "light"; }, [dark]);
  const [confirm, setConfirm] = useState<Confirm>(null);
  const [draft, setDraft] = useState<Policy | null>(null);
  const [failRead, setFailRead] = useState(false);
  const [tour, setTour] = useState<number | null>(null);
  const [tourRect, setTourRect] = useState<DOMRect | null>(null);
  const [showJson, setShowJson] = useState(false);

  useEffect(() => { const onHash = () => { setLocationState(route()); setSearch(""); }; addEventListener("hashchange", onHash); return () => removeEventListener("hashchange", onHash); }, []);
  const go = (page: Page, id?: string) => { location.hash = `/${page}${id ? `/${id}` : ""}`; setLocationState({ page, id }); setSearch(""); };
  const { page, id: pageId } = locationState;
  const key = data.keys.find(k => k.id === pageId);
  useEffect(() => { setDraft(key ? copy(key.policy) : null); setShowJson(false); }, [key?.id]);
  const activePolicy = draft || key?.policy;
  const predicted = activePolicy ? exposed(activePolicy, data.groups, data.models) : [];
  const observed = key?.observed || [];
  const diff = delta(observed, predicted);
  const isDirty = Boolean(key && draft && !same(key.policy, draft));
  const families = ["All providers", ...new Set(data.models.flatMap(m => m.accesses.map(a => a.provider)))];
  const filteredModels = data.models.filter(m => {
    const q = search.toLowerCase();
    return (!q || `${m.name} ${m.id} ${m.family} ${m.summary} ${m.accesses.map(a => a.provider).join(" ")}`.toLowerCase().includes(q)) &&
      (family === "All providers" || m.accesses.some(a => a.provider === family)) && (kind === "All types" || m.kind === kind);
  });
  const filteredGroups = data.groups.filter(g => `${g.name} ${g.description}`.toLowerCase().includes(search.toLowerCase()));
  const filteredKeys = data.keys.filter(k => `${k.name} ${k.client}`.toLowerCase().includes(search.toLowerCase()));

  const newModel = (): Model => ({ id: "", name: "", family: "", kind: "Chat", summary: "", context: "Unknown", capabilities: { Chat: "Unknown", Streaming: "Unknown", Tools: "Unknown", Vision: "Unknown" }, accesses: [{ provider: "", id: "", route: "Direct provider", status: "Unknown" }] });
  const updateModel = () => {
    if (!modelDraft) return;
    if (!/^[a-z0-9][a-z0-9._-]*$/.test(modelDraft.id) || !modelDraft.name.trim() || !modelDraft.family.trim() || !modelDraft.accesses.length || !modelDraft.accesses.every(a => a.provider.trim() && a.id.trim())) { setModelError("Enter a model ID, name, family, and at least one complete provider access."); return; }
    const existing = !creatingModel;
    if (creatingModel && data.models.some(m => m.id === modelDraft.id)) { setModelError("That model ID already exists."); return; }
    const allAccessIds = data.models.filter(m => m.id !== modelDraft.id).flatMap(m => m.accesses.map(a => a.id));
    if (modelDraft.accesses.some(a => allAccessIds.includes(a.id)) || new Set(modelDraft.accesses.map(a => a.id)).size !== modelDraft.accesses.length) { setModelError("Provider access IDs must be unique."); return; }
    setData(old => ({ ...old, models: existing ? old.models.map(m => m.id === modelDraft.id ? copy(modelDraft) : m) : [...old.models, copy(modelDraft)] }));
    setModelDraft(null); setModelError(""); toast.success(existing ? "Model updated in demo." : "Model created in demo.");
  };
  const deleteModel = (model: Model) => {
    setModelDraft(null);
    const used = data.keys.filter(k => members(k.policy, data.groups).includes(model.id)).length;
    setConfirm({ title: `Delete ${model.name}?`, text: `This removes the model from its groups and key selections. ${used} key catalog${used === 1 ? "" : "s"} will change.`, action: () => {
      setData(old => {
        const models = old.models.filter(m => m.id !== model.id);
        const groups = old.groups.map(g => ({ ...g, members: g.members.filter(id => id !== model.id) }));
        const keys = old.keys.map(k => {
          const policy = { ...k.policy, added: k.policy.added.filter(id => id !== model.id), excluded: k.policy.excluded.filter(id => id !== model.id) };
          return { ...k, policy, observed: failRead ? k.observed : exposed(policy, groups, models), readError: failRead };
        });
        return { ...old, models, groups, keys };
      });
      toast.success("Model deleted in demo.");
    } });
  };
  const publishGroup = () => {
    if (!groupDraft?.name.trim()) { toast.error("Enter a group name."); return; }
    const exists = data.groups.some(g => g.id !== groupDraft.id && g.name.toLowerCase() === groupDraft.name.trim().toLowerCase());
    if (exists) { toast.error("A group with this name already exists."); return; }
    const nextGroup = { ...groupDraft, name: groupDraft.name.trim() };
    const nextGroups = data.groups.some(g => g.id === groupDraft.id) ? data.groups.map(g => g.id === groupDraft.id ? nextGroup : g) : [...data.groups, nextGroup];
    const impacted = keyImpact(data.keys, data.groups, nextGroups, data.models);
    setData(old => ({ ...old, groups: nextGroups, keys: old.keys.map(k => impacted.some(x => x.key.id === k.id) ? { ...k, observed: failRead ? k.observed : exposed(k.policy, nextGroups, old.models), readError: failRead, revision: k.revision + 1 } : k) }));
    setGroupDraft(null);
    toast[failRead ? "warning" : "success"](failRead ? "Group published; simulated readback failed." : `Group published; ${impacted.length} key catalog${impacted.length === 1 ? "" : "s"} updated.`);
  };
  const saveKey = () => {
    if (!keyForm?.name.trim()) { toast.error("Enter a key name."); return; }
    if (data.keys.some(k => k.name.toLowerCase() === keyForm.name.trim().toLowerCase())) { toast.error("A key with this name already exists."); return; }
    const id = crypto.randomUUID();
    const newKey: Key = { id, name: keyForm.name.trim(), client: keyForm.client.trim() || "Unassigned", active: true, policy: { groups: [], added: [], excluded: [], naming: "model" }, observed: [], readError: false, revision: 1 };
    setData(old => ({ ...old, keys: [...old.keys, newKey] })); setKeyForm(null); go("keys", id); toast.success("Virtual key created in the demo. No secret was generated.");
  };
  const publishKey = () => {
    if (!key || !draft) return;
    const expected = exposed(draft, data.groups, data.models);
    setData(old => ({ ...old, keys: old.keys.map(k => k.id === key.id ? { ...k, policy: copy(draft), observed: failRead ? k.observed : expected, readError: failRead, revision: k.revision + 1 } : k) }));
    toast[failRead ? "warning" : "success"](failRead ? "Published in the demo; readback is unavailable." : "Published and read back in the demo.");
  };
  const reread = () => {
    if (!key) return;
    setData(old => ({ ...old, keys: old.keys.map(k => k.id === key.id ? { ...k, observed: failRead ? k.observed : exposed(k.policy, old.groups, old.models), readError: failRead } : k) }));
    toast[failRead ? "error" : "success"](failRead ? "Simulated readback unavailable. Last result retained." : "Simulated /v1/models readback updated.");
  };
  const reset = () => { setData(copy(fixture)); setDraft(null); setGroupDraft(null); setModelDraft(null); setConfirm(null); setFailRead(false); setSearch(""); setFamily("All providers"); setKind("All types"); go("models"); toast.success("Demo reset."); };
  const downloadJson = () => {
    if (!key) return;
    const payload = { object: "list", data: observed.map(id => ({ id, object: "model" })) };
    const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" })); link.download = `${key.name.toLowerCase().replace(/\s+/g, "-")}-simulated-models.json`; link.click(); URL.revokeObjectURL(link.href);
  };
  const runCampaign = () => {
    if (!campaignForm?.access) { toast.error("Choose a model access."); return; }
    const model = data.models.find(m => m.accesses.some(a => a.id === campaignForm.access));
    const access = model?.accesses.find(a => a.id === campaignForm.access);
    if (!model || !access) { toast.error("That access is no longer available."); return; }
    const result: Campaign = { id: `run-${crypto.randomUUID().slice(0, 6)}`, model: model.id, provider: access.provider, accessId: access.id, scenario: campaignForm.scenario, outcome: campaignForm.outcome, date: new Date().toISOString().slice(0, 10), note: campaignForm.outcome === "Inconclusive" ? "Illustrative timeout; cause cannot be attributed to model, provider, or gateway." : "Illustrative fixture response; no provider or gateway request was made." };
    setData(old => ({ ...old, campaigns: [result, ...old.campaigns] })); setCampaignForm(null); setReport(result); toast.success("Simulated campaign added.");
  };

  const tourSteps = [
    { page: "models" as Page, selector: "[data-tour='first-model']", title: "One model, several accesses", detail: "Open a card to compare providers and evidence." },
    { page: "models" as Page, selector: "[data-tour='filters']", title: "Find the right model", detail: "Search or filter by provider and type." },
    { page: "groups" as Page, selector: "[data-tour='groups']", title: "Shared groups", detail: "Edit once and preview which keys will change." },
    { page: "keys" as Page, selector: "[data-tour='keys']", title: "Virtual keys", detail: "Open Hermes to compose its catalog." },
    { page: "keys" as Page, id: "hermes", selector: "[data-tour='composer']", title: "Local choices", detail: "Combine groups, single models, and key-only exclusions." },
    { page: "keys" as Page, id: "hermes", selector: "[data-tour='preview']", title: "Preview and readback", detail: "The draft and the last simulated /v1/models response stay separate." },
  ];
  useEffect(() => {
    if (tour === null) return;
    const step = tourSteps[tour];
    if (page !== step.page || pageId !== step.id) { go(step.page, step.id); return; }
    const update = () => setTourRect(document.querySelector(step.selector)?.getBoundingClientRect() || null);
    const timer = setTimeout(() => { document.querySelector(step.selector)?.scrollIntoView({ block: "center" }); update(); }, 80); addEventListener("resize", update); addEventListener("scroll", update, true);
    return () => { clearTimeout(timer); removeEventListener("resize", update); removeEventListener("scroll", update, true); };
  }, [tour, page, pageId, data]);

  const title = page === "models" ? "Model Catalog" : page === "groups" ? "Groups" : page === "qualification" ? "Qualification" : key ? key.name : "Virtual Keys";
  return <TooltipProvider delayDuration={0}><SidebarProvider><Sidebar inert={tour !== null} collapsible="icon" className="border-none bg-transparent"><SidebarHeader className="px-4 pt-5 pb-3"><div className="flex items-center justify-between gap-2"><a href="#/models" onClick={() => go("models")} className="min-w-0"><img src="/bifrost-logo.webp" alt="Bifrost" className="h-[22px] max-w-[145px] object-contain object-left dark:hidden" /><img src="/bifrost-logo-dark.webp" alt="Bifrost" className="hidden h-[22px] max-w-[145px] object-contain object-left dark:block" /></a><SidebarTrigger className="size-7" /></div></SidebarHeader><SidebarContent><SidebarGroup><SidebarGroupLabel>WORKSPACE</SidebarGroupLabel><SidebarGroupContent><SidebarMenu>{nav.map(item => { const Icon = item.icon; return <SidebarMenuItem key={item.id}><SidebarMenuButton asChild isActive={page === item.id} tooltip={item.label}><a href={`#/${item.id}`} onClick={() => go(item.id)} className={page === item.id ? "border border-primary/20 text-primary" : "border border-transparent"}><Icon className="size-4" /><span>{item.label}</span></a></SidebarMenuButton></SidebarMenuItem>; })}</SidebarMenu></SidebarGroupContent></SidebarGroup></SidebarContent><SidebarFooter className="p-4"><span className="text-xs text-muted-foreground group-data-[collapsible=icon]:hidden">Registry prototype</span></SidebarFooter></Sidebar>
    <div inert={tour !== null} className="flex h-dvh w-full min-w-0 flex-col"><header className="flex h-13 w-full shrink-0 items-center gap-2 px-3 pt-1 md:pr-3 md:pl-0"><SidebarTrigger className="md:hidden" /><h1 className="min-w-0 flex-1 truncate text-base font-semibold">{key && page === "keys" ? <><button onClick={() => go("keys")} className="text-muted-foreground hover:text-foreground">Virtual Keys</button><span className="mx-2 text-muted-foreground/50">/</span>{title}</> : title}</h1><Tooltip><TooltipTrigger asChild><CircleHelp className="hidden size-4 cursor-help text-muted-foreground sm:block" /></TooltipTrigger><TooltipContent>{page === "models" ? "Explore models and provider accesses" : page === "groups" ? "Shared sets of models for keys" : page === "keys" ? "Compose and publish key catalogs" : "Illustrative harness coverage and campaigns"}</TooltipContent></Tooltip><div className="ml-auto flex items-center gap-2"><Badge variant="warning" className="text-[10px]"><span className="sm:hidden">DEMO</span><span className="hidden sm:inline">SIMULATION</span></Badge><Popover><PopoverTrigger asChild><Button variant="ghost" size="icon" aria-label="Demo settings" title="Demo settings"><Settings2 className="size-4" /></Button></PopoverTrigger><PopoverContent align="end" className="w-64"><h3 className="mb-2 text-sm font-medium">Demo settings</h3><label className="flex items-center justify-between gap-3 text-xs"><span>Simulate readback failures</span><Switch checked={failRead} onCheckedChange={setFailRead} /></label><p className="mt-2 text-xs text-muted-foreground">All actions use browser memory only.</p><Button variant="outline" size="sm" className="mt-3 w-full" onClick={reset}><RotateCcw className="size-3.5" />Reset demo</Button></PopoverContent></Popover><Button variant="ghost" size="icon" aria-label={dark ? "Use light theme" : "Use dark theme"} title={dark ? "Use light theme" : "Use dark theme"} onClick={() => setDark(!dark)}>{dark ? <Sun className="size-4" /> : <Moon className="size-4" />}</Button><Button variant="ghost" size="sm" aria-label="Quick tour" onClick={() => setTour(0)}><BookOpen className="size-4" /><span className="hidden sm:inline">Quick tour</span></Button><div className="hidden items-center gap-2 rounded-full border bg-card px-2 py-1 md:flex"><span className="flex size-5 items-center justify-center rounded-full bg-muted text-[10px] font-semibold">S</span><span className="text-xs font-medium">Sofian</span><ChevronDown className="size-3 text-muted-foreground" /></div></div></header>
      <div className="custom-scrollbar content-container mx-0 min-h-0 min-w-0 flex-1 overflow-auto border border-gray-200 bg-white md:mr-3 md:mb-3 md:rounded-md md:px-10 dark:border-zinc-800 dark:bg-card"><main className="mx-auto max-w-[1440px] px-4 py-5 md:px-0 md:py-7">
        {page === "models" && <><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-semibold">Models</h2><p className="mt-1 text-sm text-muted-foreground">Explore one model across its configured provider accesses.</p></div><div className="flex items-center gap-2"><Badge variant="secondary">{data.models.length} models · {data.models.reduce((n, m) => n + m.accesses.length, 0)} accesses</Badge><Button onClick={() => { setCreatingModel(true); setModelError(""); setModelDraft(newModel()); }}><Plus className="size-4" />Add model</Button></div></div>
          <div className="mb-5 grid grid-cols-3 gap-2 sm:gap-3"><Card className="gap-1 py-4"><CardContent><div className="text-xs text-muted-foreground">Available models</div><div className="mt-1 text-2xl font-semibold">{data.models.length}</div></CardContent></Card><Card className="gap-1 py-4"><CardContent><div className="text-xs text-muted-foreground">Provider accesses</div><div className="mt-1 text-2xl font-semibold">{data.models.reduce((n, m) => n + m.accesses.length, 0)}</div></CardContent></Card><Card className="gap-1 py-4"><CardContent><div className="text-xs text-muted-foreground">Campaigns</div><div className="mt-1 text-2xl font-semibold">{data.campaigns.length}</div></CardContent></Card></div>
          <div data-tour="filters" className="mb-5 flex flex-wrap items-center gap-2"><div className="relative min-w-[220px] flex-1 sm:max-w-sm"><Search className="absolute top-2.5 left-3 size-4 text-muted-foreground" /><Input aria-label="Search models" placeholder="Search models or providers..." className="pl-9" value={search} onChange={e => setSearch(e.target.value)} /></div><UiSelect label="Provider" value={family} onChange={setFamily} options={families} /><UiSelect label="Model type" value={kind} onChange={setKind} options={["All types", "Chat", "Vision", "Image", "Embedding"]} /></div>
          <div className="grid gap-3 min-[560px]:grid-cols-2 xl:grid-cols-3">{filteredModels.map((m, index) => <Card key={m.id} data-tour={index === 0 ? "first-model" : undefined} className="group gap-4 py-0 transition-colors hover:border-primary/40"><CardHeader className="border-b py-4"><div className="flex items-start justify-between gap-2"><div className="flex min-w-0 items-center gap-3"><span className="flex size-9 shrink-0 items-center justify-center rounded-sm border bg-muted text-sm font-semibold text-muted-foreground">{m.name.slice(0, 1)}</span><div className="min-w-0"><CardTitle className="truncate text-sm">{m.name}</CardTitle><p className="mt-1 text-xs text-muted-foreground">{m.family} · {m.kind}</p></div></div><Badge variant="secondary">{m.accesses.length} access{m.accesses.length === 1 ? "" : "es"}</Badge></div></CardHeader><CardContent className="flex min-h-32 flex-col pb-4"><p className="line-clamp-2 min-h-10 text-sm text-muted-foreground">{m.summary}</p><div className="mt-3 flex flex-wrap gap-1">{m.accesses.map(a => <Badge key={a.id} variant="outline" className="font-mono font-normal">{a.provider}</Badge>)}</div><div className="mt-auto flex items-center justify-between pt-4"><span className="text-xs text-muted-foreground">{Object.values(m.capabilities).filter(x => x === "Observed in simulated campaign").length} observed capabilities</span><Button variant="outline" size="sm" onClick={() => { setCreatingModel(false); setModelError(""); setModelDraft(copy(m)); }}>View details <ArrowRight className="size-3.5" /></Button></div></CardContent></Card>)}</div>{!filteredModels.length && <Empty icon={Search} title="No matching models" detail="Try another search or clear your filters." action={<Button variant="outline" onClick={() => { setSearch(""); setFamily("All providers"); setKind("All types"); }}>Clear filters</Button>} />}</>}
        {page === "groups" && <><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-semibold">Groups</h2><p className="mt-1 text-sm text-muted-foreground">Reusable model selections shared by virtual keys.</p></div><Button data-tour="groups" onClick={() => setGroupDraft({ id: crypto.randomUUID(), name: "", description: "", members: [] })}><Plus className="size-4" />Create group</Button></div><div className="mb-4 max-w-sm"><div className="relative"><Search className="absolute top-2.5 left-3 size-4 text-muted-foreground" /><Input aria-label="Search groups" placeholder="Search groups..." className="pl-9" value={search} onChange={e => setSearch(e.target.value)} /></div></div><div className="overflow-hidden rounded-sm border"><Table><TableHeader><TableRow><TableHead>Group</TableHead><TableHead>Models</TableHead><TableHead>Used by</TableHead><TableHead className="text-right">Action</TableHead></TableRow></TableHeader><TableBody>{filteredGroups.map(g => <TableRow key={g.id} className="cursor-pointer" onClick={() => setGroupDraft(copy(g))}><TableCell><div className="font-medium">{g.name}</div><div className="mt-1 text-xs text-muted-foreground">{g.description || "No description"}</div></TableCell><TableCell>{g.members.length} models</TableCell><TableCell className="space-x-1">{data.keys.filter(k => k.policy.groups.includes(g.id)).map(k => <Badge key={k.id} variant="secondary" className="font-mono">{k.name}</Badge>)}{!data.keys.some(k => k.policy.groups.includes(g.id)) && <span className="text-muted-foreground">—</span>}</TableCell><TableCell className="text-right"><Button size="sm" variant="ghost" onClick={e => { e.stopPropagation(); setGroupDraft(copy(g)); }}>Edit <ArrowRight className="size-3.5" /></Button></TableCell></TableRow>)}</TableBody></Table></div>{!filteredGroups.length && <Empty icon={Layers3} title="No matching groups" detail={data.groups.length ? "Try another search." : "Create a group to reuse its models across keys."} action={<Button onClick={() => { setSearch(""); setGroupDraft({ id: crypto.randomUUID(), name: "", description: "", members: [] }); }}>Create group</Button>} />}</>}
        {page === "keys" && !key && <><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-semibold">Virtual Keys</h2><p className="mt-1 text-sm text-muted-foreground">Create a key, compose its catalog, and inspect simulated readback.</p></div><Button onClick={() => setKeyForm({ name: "", client: "" })}><Plus className="size-4" />Create key</Button></div><div className="mb-4 max-w-sm"><div className="relative"><Search className="absolute top-2.5 left-3 size-4 text-muted-foreground" /><Input aria-label="Search keys" placeholder="Search keys..." className="pl-9" value={search} onChange={e => setSearch(e.target.value)} /></div></div><div className="overflow-hidden rounded-sm border"><Table><TableHeader><TableRow><TableHead>Key</TableHead><TableHead>Client</TableHead><TableHead>Groups</TableHead><TableHead>Models</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Action</TableHead></TableRow></TableHeader><TableBody>{filteredKeys.map((k, index) => <TableRow key={k.id} data-tour={index === 0 ? "keys" : undefined} className="cursor-pointer" onClick={() => go("keys", k.id)}><TableCell className="font-medium">{k.name}</TableCell><TableCell className="text-muted-foreground">{k.client}</TableCell><TableCell>{k.policy.groups.map(id => data.groups.find(g => g.id === id)?.name).filter(Boolean).join(", ") || "—"}</TableCell><TableCell>{members(k.policy, data.groups).length}</TableCell><TableCell><Badge variant={k.active ? "success" : "secondary"}>{k.active ? "Active" : "Disabled"}</Badge></TableCell><TableCell className="text-right"><Button variant="ghost" size="sm" onClick={e => { e.stopPropagation(); go("keys", k.id); }}>Open <ArrowRight className="size-3.5" /></Button></TableCell></TableRow>)}</TableBody></Table></div>{!filteredKeys.length && <Empty icon={KeyRound} title="No matching keys" detail={data.keys.length ? "Try another search." : "Create a virtual key to start composing a catalog."} action={<Button onClick={() => { setSearch(""); setKeyForm({ name: "", client: "" }); }}>Create key</Button>} />}</>}
        {page === "keys" && key && activePolicy && <><div className="mb-5 flex flex-wrap items-start justify-between gap-3"><div><Button variant="ghost" size="sm" className="mb-2 -ml-2" onClick={() => go("keys")}><ArrowLeft className="size-4" />All keys</Button><div className="flex items-center gap-2"><h2 className="text-xl font-semibold">{key.name}</h2><Badge variant={key.active ? "success" : "secondary"}>{key.active ? "Active" : "Disabled"}</Badge></div><p className="mt-1 text-sm text-muted-foreground">{key.client} · Revision {key.revision} · Credential simulated, no secret generated</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => setRenameForm({ id: key.id, name: key.name })}>Rename</Button><Button variant="outline" onClick={() => setData(old => ({ ...old, keys: old.keys.map(x => x.id === key.id ? { ...x, active: !x.active } : x) }))}>{key.active ? "Disable" : "Enable"}</Button><Button variant="ghost" size="icon" aria-label="Delete key" onClick={() => setConfirm({ title: `Delete ${key.name}?`, text: "This removes the simulated key and its local catalog configuration.", action: () => { setData(old => ({ ...old, keys: old.keys.filter(x => x.id !== key.id) })); go("keys"); toast.success("Key deleted in demo."); } })}><Trash2 className="size-4 text-destructive" /></Button></div></div>
          <div className="grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(340px,.75fr)]"><div className="space-y-5"><Card className="gap-4 py-5"><CardHeader><CardTitle className="text-base">Compose catalog</CardTitle><p className="text-xs text-muted-foreground">Changes apply only to {key.name}. Shared groups are managed separately.</p></CardHeader><CardContent className="space-y-5"><section data-tour="composer"><div className="mb-2 flex items-center justify-between"><h3 className="text-sm font-medium">Shared groups</h3><Button variant="link" size="sm" onClick={() => go("groups")}>Manage groups <ArrowRight className="size-3.5" /></Button></div><div className="grid gap-2 sm:grid-cols-2">{data.groups.map(g => <label key={g.id} className="flex cursor-pointer items-center gap-3 rounded-sm border p-3 hover:bg-muted/40"><Checkbox checked={activePolicy.groups.includes(g.id)} onCheckedChange={checked => setDraft(old => old ? { ...old, groups: checked ? [...old.groups, g.id] : old.groups.filter(x => x !== g.id) } : old)} /><span className="flex-1"><span className="block text-sm font-medium">{g.name}</span><span className="text-xs text-muted-foreground">{g.members.length} models</span></span></label>)}</div>{!data.groups.length && <p className="text-sm text-muted-foreground">No groups yet. Add individual models below or create a group.</p>}</section><section><h3 className="mb-2 text-sm font-medium">Models and local exceptions</h3><p className="mb-3 text-xs text-muted-foreground">An exclusion here does not change a shared group or another key.</p><div className="max-h-80 overflow-auto rounded-sm border"><Table><TableHeader><TableRow><TableHead>Model</TableHead><TableHead>Source</TableHead><TableHead className="text-right">Selection</TableHead></TableRow></TableHeader><TableBody>{data.models.map(m => { const inherited = origin(m.id, activePolicy, data.groups); const excluded = activePolicy.excluded.includes(m.id); const active = members(activePolicy, data.groups).includes(m.id); return <TableRow key={m.id}><TableCell><span className="font-medium">{m.name}</span><span className="block text-xs text-muted-foreground">{m.kind}</span></TableCell><TableCell className="text-xs text-muted-foreground">{excluded ? "Excluded on this key" : inherited.length ? `Group: ${inherited.join(", ")}` : active ? "Added individually" : "Available"}</TableCell><TableCell className="text-right"><Button variant={active ? "outline" : "secondary"} size="sm" onClick={() => setDraft(old => old ? toggleModel(old, m.id, data.groups) : old)}>{active ? inherited.length ? "Exclude" : "Remove" : excluded ? "Restore" : "Add"}</Button></TableCell></TableRow>; })}</TableBody></Table></div></section><section><h3 className="mb-2 text-sm font-medium">Visible model names</h3><div className="flex flex-wrap gap-2">{formats.map(format => <Button key={format} variant={activePolicy.naming === format ? "default" : "outline"} size="sm" onClick={() => setDraft(old => old ? { ...old, naming: format } : old)}>{format}</Button>)}</div><p className="mt-2 text-xs text-muted-foreground">Short names use the explicitly configured Bifrost route. Multiple accesses do not imply load balancing.</p></section></CardContent></Card><div className="flex flex-wrap items-center gap-2"><Button disabled={!isDirty} onClick={publishKey}>Publish changes</Button><Button variant="outline" disabled={!isDirty} onClick={() => { setDraft(copy(key.policy)); toast.success("Draft discarded."); }}>Discard draft</Button><span className="text-xs text-muted-foreground">{isDirty ? "Unpublished changes" : "Draft matches published policy"}</span></div></div>
          <div className="space-y-4"><Card data-tour="preview" className="gap-4 py-5"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Eye className="size-4" />Live draft preview</CardTitle><p className="text-xs text-muted-foreground">Expected from the current editor state · {predicted.length} IDs</p></CardHeader><CardContent><div className="max-h-56 space-y-1 overflow-auto">{predicted.map(id => <div key={id} className="flex items-center justify-between rounded-sm border px-3 py-2 font-mono text-xs"><span>{id}</span>{diff.added.includes(id) && <Badge variant="success">+ new</Badge>}</div>)}{!predicted.length && <p className="rounded-sm border border-dashed p-6 text-center text-sm text-muted-foreground">This key would see no models.</p>}</div>{diff.removed.length > 0 && <p className="mt-3 text-xs text-destructive">To remove: {diff.removed.join(", ")}</p>}</CardContent></Card><Card className="gap-4 py-5"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Activity className="size-4" />Last simulated readback</CardTitle><p className="text-xs text-muted-foreground">Independent /v1/models response · {observed.length} IDs</p></CardHeader><CardContent><div className="mb-3 flex flex-wrap items-center gap-2"><Badge variant={key.readError ? "warning" : "success"}>{key.readError ? "Readback unavailable" : "Readback complete"}</Badge><Button variant="outline" size="sm" onClick={reread}><RotateCcw className="size-3.5" />Read again</Button><Button variant="ghost" size="sm" onClick={downloadJson}><FileJson className="size-3.5" />Export JSON</Button></div>{key.readError && <p className="mb-3 text-xs text-amber-700">Last successful response is retained. Current published result is unverified.</p>}<div className="max-h-44 space-y-1 overflow-auto">{observed.map(id => <div key={id} className="rounded-sm border px-3 py-2 font-mono text-xs">{id}</div>)}{!observed.length && <p className="text-sm text-muted-foreground">No models in the last response.</p>}</div><Button variant="link" size="sm" className="mt-2 px-0" onClick={() => setShowJson(!showJson)}>{showJson ? "Hide" : "Show"} response JSON</Button>{showJson && <pre className="max-h-56 overflow-auto rounded-sm bg-muted p-3 text-[11px]">{JSON.stringify({ object: "list", data: observed.map(id => ({ id, object: "model" })) }, null, 2)}</pre>}</CardContent></Card></div></div></>}
        {page === "qualification" && <><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-semibold">Qualification</h2><p className="mt-1 text-sm text-muted-foreground">Harness coverage and illustrative campaign outcomes. No live test is run here.</p></div><Button disabled={!data.models.length} onClick={() => setCampaignForm({ access: data.models[0]?.accesses[0]?.id || "", scenario: scenariosFor(data.models[0])[0], outcome: "Pass" })}><Plus className="size-4" />New campaign</Button></div><div className="mb-5 grid gap-3 md:grid-cols-3"><Card className="gap-2 py-4"><CardContent><div className="flex items-center gap-2 text-xs text-muted-foreground"><ShieldCheck className="size-4" />Harness scenarios</div><div className="mt-2 text-xl font-semibold">3 mapped</div><p className="mt-1 text-xs text-muted-foreground">Chat, streaming, tool round trip</p></CardContent></Card><Card className="gap-2 py-4"><CardContent><div className="flex items-center gap-2 text-xs text-muted-foreground"><Check className="size-4" />Illustrative passes</div><div className="mt-2 text-xl font-semibold">{data.campaigns.filter(c => c.outcome === "Pass").length}</div><p className="mt-1 text-xs text-muted-foreground">Fixture results, not certified access</p></CardContent></Card><Card className="gap-2 py-4"><CardContent><div className="flex items-center gap-2 text-xs text-muted-foreground"><CircleHelp className="size-4" />Unknown or inconclusive</div><div className="mt-2 text-xl font-semibold">{data.campaigns.filter(c => c.outcome !== "Pass").length}</div><p className="mt-1 text-xs text-muted-foreground">No negative capability inferred</p></CardContent></Card></div><div className="mb-3 flex items-center justify-between"><h3 className="text-sm font-semibold">Recent campaigns</h3><span className="text-xs text-muted-foreground">Source: illustrative Test Harness mapping</span></div><div className="overflow-hidden rounded-sm border"><Table><TableHeader><TableRow><TableHead>Run</TableHead><TableHead>Model access</TableHead><TableHead>Scenario</TableHead><TableHead>Result</TableHead><TableHead>Date</TableHead><TableHead className="text-right">Report</TableHead></TableRow></TableHeader><TableBody>{data.campaigns.map(c => <TableRow key={c.id}><TableCell className="font-mono text-xs">{c.id}</TableCell><TableCell className="font-mono text-xs">{c.accessId}</TableCell><TableCell><span className="font-medium">{c.scenario}</span><p className="mt-1 text-xs text-muted-foreground">{c.note}</p></TableCell><TableCell><Badge variant={statusStyle(c.outcome)}>{c.outcome}</Badge></TableCell><TableCell className="text-muted-foreground">{c.date}</TableCell><TableCell className="text-right"><Button variant="ghost" size="sm" onClick={() => setReport(c)}>Open report <ArrowRight className="size-3.5" /></Button></TableCell></TableRow>)}</TableBody></Table></div><p className="mt-4 text-xs text-muted-foreground">A missing scenario means “not tested”. A timeout does not establish whether the limit belongs to the model, provider access, or gateway.</p></>}
      </main></div></div>
    <Sheet open={!!modelDraft} onOpenChange={open => !open && setModelDraft(null)}><SheetContent className="p-6"><SheetHeader><SheetTitle>{creatingModel ? "Add model" : modelDraft?.name}</SheetTitle><SheetDescription className="sr-only">Edit the model details, provider accesses, and capabilities.</SheetDescription></SheetHeader>{modelDraft && <div className="custom-scrollbar flex-1 space-y-6 overflow-auto pr-2">{creatingModel && <div><label className="mb-2 block text-sm font-medium">Model ID *</label><Input aria-label="Model ID" value={modelDraft.id} onChange={e => setModelDraft({ ...modelDraft, id: e.target.value })} placeholder="model-id" /></div>}<div><label className="mb-2 block text-sm font-medium">Display name *</label><Input aria-label="Display name" value={modelDraft.name} onChange={e => setModelDraft({ ...modelDraft, name: e.target.value })} /></div><div><label className="mb-2 block text-sm font-medium">Family *</label><Input aria-label="Family" value={modelDraft.family} onChange={e => setModelDraft({ ...modelDraft, family: e.target.value })} placeholder="e.g. OpenAI" /></div><div><label className="mb-2 block text-sm font-medium">Description</label><Textarea aria-label="Description" value={modelDraft.summary} onChange={e => setModelDraft({ ...modelDraft, summary: e.target.value })} /></div><div className="grid grid-cols-2 gap-3"><div><label className="mb-2 block text-sm font-medium">Type</label><UiSelect label="Model type" className="w-full" value={modelDraft.kind} onChange={value => setModelDraft({ ...modelDraft, kind: value as Model["kind"] })} options={["Chat", "Vision", "Image", "Embedding"]} /></div><div><label className="mb-2 block text-sm font-medium">Context window</label><Input aria-label="Context window" value={modelDraft.context} onChange={e => setModelDraft({ ...modelDraft, context: e.target.value })} /></div></div><section><h3 className="mb-2 text-sm font-semibold">Provider accesses *</h3><div className="space-y-2">{modelDraft.accesses.map((a, i) => <div key={i} className="rounded-sm border p-3"><div className="mb-2 flex items-center justify-between"><span className="text-xs text-muted-foreground">Access {i + 1}</span><Button variant="ghost" size="icon" aria-label={`Remove access ${i + 1}`} disabled={modelDraft.accesses.length === 1} onClick={() => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.filter((_, j) => i !== j) })}><X className="size-4" /></Button></div><div className="grid gap-2 sm:grid-cols-2"><Input aria-label="Provider" placeholder="Provider" value={a.provider} onChange={e => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.map((x, j) => i === j ? { ...x, provider: e.target.value } : x) })} /><Input aria-label="Exposed provider ID" placeholder="provider/model" value={a.id} onChange={e => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.map((x, j) => i === j ? { ...x, id: e.target.value } : x) })} /></div><div className="mt-2 flex items-center justify-between"><span className="text-xs text-muted-foreground">Route: {a.route}</span><UiSelect label="Access status" value={a.status} onChange={value => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.map((x, j) => i === j ? { ...x, status: value as Access["status"] } : x) })} options={["Configured", "Unknown"]} /></div></div>)}</div><Button variant="outline" size="sm" className="mt-2" onClick={() => setModelDraft({ ...modelDraft, accesses: [...modelDraft.accesses, { provider: "", id: "", route: "Direct provider", status: "Unknown" }] })}><Plus className="size-3.5" />Add access</Button><p className="mt-2 text-xs text-muted-foreground">Short-name routing is configured separately. These rows do not define a load balancer.</p></section><section><h3 className="mb-2 text-sm font-semibold">Capabilities and evidence</h3><div className="space-y-2">{Object.entries(modelDraft.capabilities).map(([name, value]) => <div key={name} className="flex items-center justify-between gap-2 rounded-sm border px-3 py-2"><span className="text-sm">{name}</span><UiSelect label={`${name} evidence`} className="max-w-[230px]" value={value} onChange={value => setModelDraft({ ...modelDraft, capabilities: { ...modelDraft.capabilities, [name]: value as Capability } })} options={["Declared", "Observed in simulated campaign", "Unknown"]} /></div>)}</div><p className="mt-2 text-xs text-muted-foreground">“Observed” here means an illustrative fixture only, never real certification.</p></section>{modelError && <p role="alert" className="rounded-sm border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{modelError}</p>}</div>}<SheetFooter className="flex-row justify-end border-t">{modelDraft && !creatingModel && <Button variant="ghost" className="mr-auto text-destructive" onClick={() => deleteModel(modelDraft)}>Delete</Button>}<Button variant="outline" onClick={() => setModelDraft(null)}>Cancel</Button><Button onClick={updateModel}>Save model</Button></SheetFooter></SheetContent></Sheet>
    <Sheet open={!!groupDraft} onOpenChange={open => !open && setGroupDraft(null)}><SheetContent className="p-6"><SheetHeader><SheetTitle>{groupDraft && data.groups.some(g => g.id === groupDraft.id) ? "Edit group" : "Create group"}</SheetTitle><SheetDescription className="sr-only">Choose the group models and review the impact on virtual keys.</SheetDescription></SheetHeader>{groupDraft && <div className="custom-scrollbar flex-1 space-y-5 overflow-auto pr-2"><div><label className="mb-2 block text-sm font-medium">Name</label><Input aria-label="Group name" value={groupDraft.name} onChange={e => setGroupDraft({ ...groupDraft, name: e.target.value })} /></div><div><label className="mb-2 block text-sm font-medium">Description</label><Input aria-label="Group description" value={groupDraft.description} onChange={e => setGroupDraft({ ...groupDraft, description: e.target.value })} /></div><div><h3 className="mb-2 text-sm font-medium">Models in group</h3><div className="max-h-64 space-y-1 overflow-auto rounded-sm border p-2">{data.models.map(m => <label key={m.id} className="flex cursor-pointer items-center gap-3 rounded-sm px-2 py-2 hover:bg-muted/40"><Checkbox checked={groupDraft.members.includes(m.id)} onCheckedChange={checked => setGroupDraft({ ...groupDraft, members: checked ? [...groupDraft.members, m.id] : groupDraft.members.filter(x => x !== m.id) })} /><span className="flex-1 text-sm">{m.name}</span><Badge variant="secondary">{m.kind}</Badge></label>)}</div></div><div><h3 className="mb-2 text-sm font-medium">Impact if published</h3>{(() => { const next = data.groups.some(g => g.id === groupDraft.id) ? data.groups.map(g => g.id === groupDraft.id ? groupDraft : g) : [...data.groups, groupDraft]; const impacted = keyImpact(data.keys, data.groups, next, data.models); return impacted.length ? <div className="space-y-2">{impacted.map(({ key: k, before, after }) => { const d = delta(before, after); return <div key={k.id} className="rounded-sm border p-3"><div className="font-medium">{k.name}</div><p className="mt-1 text-xs text-muted-foreground">{before.length} → {after.length} IDs · +{d.added.length} / −{d.removed.length}</p>{k.policy.excluded.length > 0 && <p className="mt-1 text-xs text-muted-foreground">Local exclusions preserved</p>}</div>; })}</div> : <p className="rounded-sm border border-dashed p-4 text-xs text-muted-foreground">No existing key catalog changes.</p>; })()}</div></div>}<SheetFooter className="flex-row justify-between border-t">{groupDraft && data.groups.some(g => g.id === groupDraft.id) && <Button variant="ghost" className="text-destructive" onClick={() => { const g = groupDraft; setGroupDraft(null); setConfirm({ title: `Delete ${g.name}?`, text: "Keys using this group will lose its models; their local selections remain.", action: () => { const next = data.groups.filter(x => x.id !== g.id); setData(old => ({ ...old, groups: next, keys: old.keys.map(k => k.policy.groups.includes(g.id) ? { ...k, policy: { ...k.policy, groups: k.policy.groups.filter(id => id !== g.id) }, observed: failRead ? k.observed : exposed({ ...k.policy, groups: k.policy.groups.filter(id => id !== g.id) }, next, old.models), readError: failRead } : k) })); toast.success("Group deleted in demo."); } }); }}>Delete</Button>}<div className="ml-auto flex gap-2"><Button variant="outline" onClick={() => setGroupDraft(null)}>Cancel</Button><Button onClick={publishGroup}>Publish group</Button></div></SheetFooter></SheetContent></Sheet>
    <Dialog open={!!keyForm} onOpenChange={open => !open && setKeyForm(null)}><DialogContent><DialogHeader><DialogTitle>Create virtual key</DialogTitle><DialogDescription>This prototype creates a simulated key record and no usable credential.</DialogDescription></DialogHeader>{keyForm && <div className="space-y-4"><div><label className="mb-2 block text-sm font-medium">Name</label><Input aria-label="Key name" autoFocus value={keyForm.name} onChange={e => setKeyForm({ ...keyForm, name: e.target.value })} placeholder="e.g. Hermes staging" /></div><div><label className="mb-2 block text-sm font-medium">Client</label><Input aria-label="Client name" value={keyForm.client} onChange={e => setKeyForm({ ...keyForm, client: e.target.value })} placeholder="e.g. Hermes" /></div></div>}<DialogFooter><Button variant="outline" onClick={() => setKeyForm(null)}>Cancel</Button><Button onClick={saveKey}>Create key</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={!!campaignForm} onOpenChange={open => !open && setCampaignForm(null)}><DialogContent><DialogHeader><DialogTitle>New campaign</DialogTitle><DialogDescription>Run an illustrative fixture only. No Bifrost or provider request is made.</DialogDescription></DialogHeader>{campaignForm && <div className="space-y-4"><div><label className="mb-2 block text-sm font-medium">Model access</label><UiSelect label="Model access" className="w-full" value={campaignForm.access} options={data.models.flatMap(m => m.accesses.map(a => a.id))} onChange={access => { const model = data.models.find(m => m.accesses.some(a => a.id === access)); setCampaignForm({ ...campaignForm, access, scenario: scenariosFor(model)[0] }); }} /></div><div><label className="mb-2 block text-sm font-medium">Scenario</label><UiSelect label="Scenario" className="w-full" value={campaignForm.scenario} options={scenariosFor(data.models.find(m => m.accesses.some(a => a.id === campaignForm.access)))} onChange={scenario => setCampaignForm({ ...campaignForm, scenario })} /></div><div><label className="mb-2 block text-sm font-medium">Fixture outcome</label><UiSelect label="Fixture outcome" className="w-full" value={campaignForm.outcome} options={["Pass", "Inconclusive"]} onChange={outcome => setCampaignForm({ ...campaignForm, outcome: outcome as Campaign["outcome"] })} /></div></div>}<DialogFooter><Button variant="outline" onClick={() => setCampaignForm(null)}>Cancel</Button><Button onClick={runCampaign}>Run simulation</Button></DialogFooter></DialogContent></Dialog>
    <Sheet open={!!report} onOpenChange={open => !open && setReport(null)}><SheetContent className="p-6"><SheetHeader><SheetTitle>Campaign report {report?.id}</SheetTitle><SheetDescription>Local fixture result. This is not evidence of a real provider capability.</SheetDescription></SheetHeader>{report && <div className="flex-1 space-y-5 overflow-auto"><Badge variant={statusStyle(report.outcome)}>{report.outcome}</Badge><div className="overflow-hidden rounded-sm border"><Table><TableBody>{[["Model", report.model], ["Provider access", report.accessId], ["Scenario", report.scenario], ["Endpoint", report.scenario === "Image generation" ? "/v1/images/generations" : report.scenario === "Embeddings" ? "/v1/embeddings" : "/v1/chat/completions"], ["Gateway version", "Not recorded for fixture"], ["Date", report.date], ["Evidence source", "Local illustrative fixture"]].map(([label, value]) => <TableRow key={label}><TableCell className="w-40 text-muted-foreground">{label}</TableCell><TableCell className="font-mono text-xs">{value}</TableCell></TableRow>)}</TableBody></Table></div><div className="rounded-sm border bg-muted/30 p-4"><h3 className="mb-2 text-sm font-medium">Interpretation</h3><p className="text-sm text-muted-foreground">{report.note}</p></div></div>}<SheetFooter className="border-t"><Button variant="outline" onClick={() => setReport(null)}>Close</Button></SheetFooter></SheetContent></Sheet>
    <Dialog open={!!renameForm} onOpenChange={open => !open && setRenameForm(null)}><DialogContent><DialogHeader><DialogTitle>Rename virtual key</DialogTitle><DialogDescription>Updates the display name in this demo.</DialogDescription></DialogHeader>{renameForm && <div><label className="mb-2 block text-sm font-medium">Name</label><Input aria-label="Key name" autoFocus value={renameForm.name} onChange={e => setRenameForm({ ...renameForm, name: e.target.value })} /></div>}<DialogFooter><Button variant="outline" onClick={() => setRenameForm(null)}>Cancel</Button><Button onClick={() => { if (!renameForm?.name.trim() || data.keys.some(k => k.id !== renameForm.id && k.name.toLowerCase() === renameForm.name.trim().toLowerCase())) { toast.error("Name is empty or already used."); return; } setData(old => ({ ...old, keys: old.keys.map(k => k.id === renameForm.id ? { ...k, name: renameForm.name.trim() } : k) })); setRenameForm(null); toast.success("Key renamed in demo."); }}>Save</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={!!confirm} onOpenChange={open => !open && setConfirm(null)}><DialogContent><DialogHeader><DialogTitle>{confirm?.title}</DialogTitle><DialogDescription>{confirm?.text}</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setConfirm(null)}>Cancel</Button><Button variant="destructive" onClick={() => { confirm?.action(); setConfirm(null); }}>Delete</Button></DialogFooter></DialogContent></Dialog>
    {tour !== null && <div className="fixed inset-0 z-[70]" aria-live="polite">
      {tourRect ? <div className="pointer-events-none fixed rounded-sm ring-2 ring-primary ring-offset-2" style={{ top: tourRect.top - 5, left: tourRect.left - 5, width: tourRect.width + 10, height: tourRect.height + 10, boxShadow: "0 0 0 9999px rgba(0,0,0,.42)" }} /> : <div className="absolute inset-0 bg-black/40" />}
      <Card role="dialog" aria-modal="true" aria-labelledby="tour-title" onKeyDown={event => { if (event.key === "Escape") setTour(null); }} className="fixed z-[71] w-[min(340px,calc(100vw-32px))] gap-3 border-primary/30 p-4 shadow-lg" style={{ top: tourRect ? tourRect.bottom + 210 < innerHeight ? tourRect.bottom + 14 : Math.max(16, tourRect.top - 205) : 90, left: tourRect ? Math.max(16, Math.min(innerWidth - Math.min(340, innerWidth - 32) - 16, tourRect.left)) : 16 }}>
        <div className="flex items-center justify-between"><Badge variant="secondary">{tour + 1} / {tourSteps.length}</Badge><Button autoFocus variant="ghost" size="icon" aria-label="Skip tour" onClick={() => setTour(null)}><X className="size-4" /></Button></div>
        <h3 id="tour-title" className="text-sm font-semibold">{tourSteps[tour].title}</h3><p className="text-xs text-muted-foreground">{tourSteps[tour].detail}</p>
        <div className="flex justify-between"><Button variant="ghost" size="sm" disabled={tour === 0} onClick={() => setTour(tour - 1)}><ArrowLeft className="size-3.5" />Back</Button><Button size="sm" onClick={() => setTour(tour === tourSteps.length - 1 ? null : tour + 1)}>{tour === tourSteps.length - 1 ? "Finish" : "Next"}<ArrowRight className="size-3.5" /></Button></div>
      </Card>
    </div>}
    <Toaster closeButton position="bottom-right" richColors />
  </SidebarProvider></TooltipProvider>;
}

function Empty({ icon: Icon, title, detail, action }: { icon: typeof Search; title: string; detail: string; action: React.ReactNode }) {
  return <div className="flex min-h-72 flex-col items-center justify-center gap-3 py-12 text-center"><Icon className="size-16 stroke-1 text-muted-foreground" /><h3 className="text-xl font-medium text-muted-foreground">{title}</h3><p className="max-w-lg text-sm text-muted-foreground">{detail}</p><div className="mt-2">{action}</div></div>;
}
